<?php

// Generated by scripts/sync-updater.sh from packages/waas-updater/src/Updater.php: edit that file
// and run the script, not this copy.

namespace WaaSHost\Updater;

// Exit if accessed directly
if ( !defined( 'ABSPATH' ) )
    exit;

/**
 * Updates for one of our plugins, from our own channel only (waas-hw4).
 *
 * The provisioning API answers GET /v1/plugins/<slug>/update with the release the site's channel
 * (or its product's pin) points at. The site authenticates with the storefront's API key and
 * secret, which the 'waas_update_credentials' filter supplies (waas-host adds it). Before
 * anything is installed, the zip's sha256 must match and its ed25519 signature must verify
 * against PUBLIC_KEYS, which are built into the plugin. There is no other source: no GitHub, no
 * wordpress.org, no fallback. If the channel can't be reached, nothing is offered and nothing
 * changes.
 *
 * Settings (wp-config.php):
 *  - WAAS_UPDATE_CHANNEL: 'stable' (default), 'beta', or 'off'.
 *  - WAAS_AUTO_UPDATE: 'patch' installs x.y.Z updates automatically; anything else, an admin clicks.
 *
 * Stores don't use this: waas-client comes with the template version and is updated by moving
 * the store to a newer one.
 *
 * Works on PHP 7.4 (waas-payments' minimum). One copy per plugin, each in that plugin's
 * namespace, made by scripts/sync-updater.sh; this file in packages/waas-updater is the source.
 */
final class Updater
{
    /**
     * base64 ed25519 public keys that may sign releases. More than one while a key is rotated.
     * Empty: updates are off, since nothing could be verified.
     */
    const PUBLIC_KEYS = [];

    /** What a release signature covers: "waas-release-v1\n<slug>\n<version>\n<sha256 hex>". */
    const SIGNATURE_CONTEXT = 'waas-release-v1';

    /** The package WordPress keeps in its update data; resolved to a fresh download link when installing. */
    const PACKAGE_SCHEME = 'waas-update://';

    const CACHE_TTL = 43200;  // 12 hours, as WordPress's own update check
    const FAILURE_TTL = 3600; // an unreachable channel is asked again after an hour

    const RELEASE_VERSION = '/^\d+\.\d+\.\d+(-beta\.\d+)?$/';

    /** @var string */
    private $slug;
    /** @var string */
    private $name;
    /** @var string plugin_basename() of the main file, like waas-host/index.php */
    private $basename;
    /** @var string */
    private $version;
    /** @var string The plugin header's Update URI */
    private $update_uri;
    /** @var string[] */
    private $public_keys;
    /** @var callable|null */
    private $credentials;

    /** @var array|\WP_Error|null This request's update info. */
    private $info = null;

    /**
     * @param array $plugin slug, name, basename, version, update_uri; optional public_keys and
     *                      credentials (a callable returning ['base_url', 'key', 'secret'] or null).
     */
    public function __construct(array $plugin)
    {
        $this->slug = $plugin['slug'];
        $this->name = $plugin['name'];
        $this->basename = $plugin['basename'];
        $this->version = $plugin['version'];
        $this->update_uri = $plugin['update_uri'];
        $this->public_keys = isset($plugin['public_keys']) ? $plugin['public_keys'] : self::PUBLIC_KEYS;
        $this->credentials = isset($plugin['credentials']) ? $plugin['credentials'] : null;
    }

    /** 'stable' or 'beta', or null when updates are off. */
    public static function channel()
    {
        $channel = defined('WAAS_UPDATE_CHANNEL') ? WAAS_UPDATE_CHANNEL : 'stable';
        return in_array($channel, ['stable', 'beta'], true) ? $channel : null;
    }

    /** Hooks into WordPress's update checks. Does nothing when updates are off or no key is trusted. */
    public function register()
    {
        if (self::channel() === null || empty($this->public_keys))
        {
            return false;
        }

        // WordPress asks "update_plugins_<host of the Update URI>" for plugins that aren't on wordpress.org.
        $host = wp_parse_url(sanitize_url($this->update_uri), PHP_URL_HOST);
        add_filter('update_plugins_' . $host, [$this, 'check_update'], 10, 3);
        add_filter('plugins_api', [$this, 'plugin_information'], 10, 3);
        add_filter('upgrader_pre_download', [$this, 'pre_download'], 10, 4);
        add_filter('upgrader_source_selection', [$this, 'keep_folder_name'], 10, 4);
        add_filter('auto_update_plugin', [$this, 'auto_update'], 10, 2);
        add_action('upgrader_process_complete', [$this, 'forget'], 10, 2);
        return true;
    }

    /** The update for WordPress's update_plugins data, or $update unchanged when there is none. */
    public function check_update($update, $plugin_data, $plugin_file)
    {
        if ($plugin_file !== $this->basename)
        {
            return $update;
        }

        // "Check again" on Dashboard > Updates asks the channel, not the cache.
        $info = $this->info(!empty($_GET['force-check']));
        if (is_wp_error($info))
        {
            return $update;
        }

        // WordPress offers it only when it's newer than the installed version, so a pin to an
        // older release never downgrades.
        return [
            'id' => $this->update_uri,
            'slug' => $this->slug,
            'plugin' => $this->basename,
            'version' => $info['version'],
            'new_version' => $info['version'],
            'url' => '',
            'package' => $this->package_marker($info['version']),
            'requires' => isset($info['requires']) ? $info['requires'] : '',
            'requires_php' => isset($info['requiresPhp']) ? $info['requiresPhp'] : '',
            'tested' => isset($info['tested']) ? $info['tested'] : '',
        ];
    }

    /** "View details" for the plugin. */
    public function plugin_information($result, $action = null, $args = null)
    {
        if ($action !== 'plugin_information' || !is_object($args) || !isset($args->slug) || $args->slug !== $this->slug)
        {
            return $result;
        }

        $info = $this->info();
        if (is_wp_error($info))
        {
            return $result;
        }

        $changelog = isset($info['changelog']) ? $info['changelog'] : '';
        return (object) [
            'name' => $this->name,
            'slug' => $this->slug,
            'version' => $info['version'],
            'requires' => isset($info['requires']) ? $info['requires'] : '',
            'requires_php' => isset($info['requiresPhp']) ? $info['requiresPhp'] : '',
            'tested' => isset($info['tested']) ? $info['tested'] : '',
            'last_updated' => isset($info['releasedAt']) ? $info['releasedAt'] : '',
            'download_link' => $this->package_marker($info['version']),
            'sections' => ['changelog' => nl2br(esc_html($changelog))],
        ];
    }

    /**
     * Downloads and checks our package. WordPress installs the file this returns; on a WP_Error it
     * stops before touching the installed plugin.
     */
    public function pre_download($reply, $package, $upgrader = null, $hook_extra = [])
    {
        $prefix = self::PACKAGE_SCHEME . $this->slug . '/';
        if ($reply !== false || !is_string($package) || strpos($package, $prefix) !== 0)
        {
            return $reply;
        }
        $wanted = substr($package, strlen($prefix));

        // The package link in the update data has long expired; ask for a fresh one.
        $info = $this->info(true);
        if (is_wp_error($info))
        {
            return new \WP_Error('waas_update_unavailable', sprintf('The %s update channel could not be reached: %s', $this->name, $info->get_error_message()));
        }
        if ($info['version'] !== $wanted)
        {
            return new \WP_Error('waas_update_changed', sprintf('The %s release changed since the last check (now %s). Check for updates again.', $this->name, $info['version']));
        }
        if (!version_compare($wanted, $this->version, '>'))
        {
            return new \WP_Error('waas_update_not_newer', sprintf('%s %s is not newer than the installed %s.', $this->name, $wanted, $this->version));
        }

        if (!function_exists('download_url'))
        {
            require_once ABSPATH . 'wp-admin/includes/file.php';
        }
        $file = download_url($info['package'], 300);
        if (is_wp_error($file))
        {
            return $file;
        }

        $error = $this->verify($file, $info);
        if ($error)
        {
            @unlink($file);
            return $error;
        }
        return $file;
    }

    /** The zip's top folder becomes the plugin's folder: keep it the installed one, or WordPress deactivates the plugin. */
    public function keep_folder_name($source, $remote_source, $upgrader = null, $hook_extra = [])
    {
        if (is_wp_error($source) || !is_array($hook_extra) || !isset($hook_extra['plugin']) || $hook_extra['plugin'] !== $this->basename)
        {
            return $source;
        }
        $folder = dirname($this->basename);
        if ($folder === '.' || basename(untrailingslashit($source)) === $folder)
        {
            return $source;
        }

        global $wp_filesystem;
        $wanted = trailingslashit($remote_source) . $folder . '/';
        if (!$wp_filesystem || !$wp_filesystem->move(untrailingslashit($source), untrailingslashit($wanted), true))
        {
            return new \WP_Error('waas_update_folder', sprintf('Could not rename the %s update folder to %s.', $this->name, $folder));
        }
        return $wanted;
    }

    /** Automatic updates only with WAAS_AUTO_UPDATE 'patch', and only for x.y.Z releases. */
    public function auto_update($update, $item)
    {
        if (!is_object($item) || !isset($item->plugin) || $item->plugin !== $this->basename)
        {
            return $update;
        }
        $policy = defined('WAAS_AUTO_UPDATE') ? WAAS_AUTO_UPDATE : 'off';
        $new = isset($item->new_version) ? $item->new_version : '';
        return $policy === 'patch' && self::is_patch_update($this->version, $new);
    }

    /** After this plugin is updated, the next check asks the channel again. */
    public function forget($upgrader = null, $hook_extra = [])
    {
        $plugins = is_array($hook_extra) && isset($hook_extra['plugins']) ? (array) $hook_extra['plugins'] : [];
        if (is_array($hook_extra) && isset($hook_extra['plugin']))
        {
            $plugins[] = $hook_extra['plugin'];
        }
        if (in_array($this->basename, $plugins, true))
        {
            $this->info = null;
            delete_site_transient($this->cache_key());
        }
    }

    /** True when $new is a later patch of the same x.y as $current, with no pre-release on either. */
    public static function is_patch_update($current, $new)
    {
        if (!preg_match('/^(\d+)\.(\d+)\.(\d+)$/', (string) $current, $a) || !preg_match('/^(\d+)\.(\d+)\.(\d+)$/', (string) $new, $b))
        {
            return false;
        }
        return $a[1] === $b[1] && $a[2] === $b[2] && (int) $b[3] > (int) $a[3];
    }

    /** Whether $signature (base64) is a valid signature by one of $public_keys of this release. */
    public static function signature_valid($slug, $version, $sha256, $signature, array $public_keys)
    {
        if (!function_exists('sodium_crypto_sign_verify_detached') || !is_string($signature))
        {
            return false;
        }
        $raw = base64_decode($signature, true);
        if ($raw === false || strlen($raw) !== 64)
        {
            return false;
        }
        $message = self::SIGNATURE_CONTEXT . "\n" . $slug . "\n" . $version . "\n" . $sha256;
        foreach ($public_keys as $key)
        {
            $public = base64_decode((string) $key, true);
            if ($public === false || strlen($public) !== 32)
            {
                continue;
            }
            try
            {
                if (sodium_crypto_sign_verify_detached($raw, $message, $public))
                {
                    return true;
                }
            }
            catch (\SodiumException $e)
            {
                continue;
            }
        }
        return false;
    }

    /** Null when the downloaded file is the release that was signed; a WP_Error otherwise. */
    private function verify($file, array $info)
    {
        $actual = @hash_file('sha256', $file);
        if (!is_string($actual) || !hash_equals($info['sha256'], $actual))
        {
            return new \WP_Error('waas_update_checksum', sprintf('The %s %s download does not match its checksum. Nothing was changed.', $this->name, $info['version']));
        }
        if (!self::signature_valid($this->slug, $info['version'], $actual, $info['signature'], $this->public_keys))
        {
            return new \WP_Error('waas_update_signature', sprintf('The %s %s download is not signed by a trusted key. Nothing was changed.', $this->name, $info['version']));
        }
        return null;
    }

    private function package_marker($version)
    {
        return self::PACKAGE_SCHEME . $this->slug . '/' . $version;
    }

    private function cache_key()
    {
        return 'waas_update_' . $this->slug . '_' . self::channel();
    }

    /** ['base_url', 'key', 'secret'] for the provisioning API, or null. */
    private function credentials()
    {
        $credentials = $this->credentials ? call_user_func($this->credentials) : apply_filters('waas_update_credentials', null);
        if (!is_array($credentials) || empty($credentials['base_url']) || empty($credentials['key']) || empty($credentials['secret']))
        {
            return null;
        }
        return $credentials;
    }

    /**
     * The release the channel offers: from this request, the cache, or the API. Failures are
     * cached for an hour so an unreachable channel isn't asked on every page load.
     *
     * @return array|\WP_Error
     */
    private function info($fresh = false)
    {
        if (!$fresh)
        {
            if ($this->info !== null)
            {
                return $this->info;
            }
            $cached = get_site_transient($this->cache_key());
            if (is_array($cached))
            {
                return $this->info = isset($cached['error']) ? new \WP_Error('waas_update_unavailable', $cached['error']) : $cached;
            }
        }

        $credentials = $this->credentials();
        if (!$credentials)
        {
            return $this->info = new \WP_Error('waas_update_no_credentials', 'The provisioning API key and secret are not set.');
        }

        $url = untrailingslashit($credentials['base_url']) . '/v1/plugins/' . rawurlencode($this->slug) . '/update?' . http_build_query([
            'version' => $this->version,
            'channel' => self::channel(),
            'site' => home_url(),
            'wp' => get_bloginfo('version'),
            'php' => PHP_VERSION,
        ], '', '&', PHP_QUERY_RFC3986);
        $response = wp_remote_get($url, [
            'timeout' => 10,
            'headers' => [
                'Authorization' => 'Basic ' . base64_encode($credentials['key'] . ':' . $credentials['secret']),
                'Accept' => 'application/json',
            ],
        ]);

        $error = null;
        if (is_wp_error($response))
        {
            $error = $response->get_error_message();
        }
        else
        {
            $code = (int) wp_remote_retrieve_response_code($response);
            $body = json_decode(wp_remote_retrieve_body($response), true);
            if ($code !== 200)
            {
                $error = sprintf('HTTP %d%s', $code, is_array($body) && isset($body['message']) && is_string($body['message']) ? ': ' . $body['message'] : '');
            }
            elseif (!$this->valid($body))
            {
                $error = 'The update channel sent an invalid answer.';
            }
        }

        if ($error !== null)
        {
            set_site_transient($this->cache_key(), ['error' => $error], self::FAILURE_TTL);
            return $this->info = new \WP_Error('waas_update_unavailable', $error);
        }

        set_site_transient($this->cache_key(), $body, self::CACHE_TTL);
        return $this->info = $body;
    }

    private function valid($body)
    {
        return is_array($body)
            && isset($body['slug'], $body['version'], $body['package'], $body['sha256'], $body['signature'])
            && $body['slug'] === $this->slug
            && is_string($body['version']) && preg_match(self::RELEASE_VERSION, $body['version'])
            && is_string($body['package']) && preg_match('#^https?://#', $body['package'])
            && is_string($body['sha256']) && preg_match('/^[0-9a-f]{64}$/', $body['sha256'])
            && is_string($body['signature']);
    }
}
